// controller/HelloDialog.js
sap.ui.define([
  "sap/ui/base/ManagedObject",
  "sap/ui/core/Fragment"
], function (ManagedObject, Fragment) {
  "use strict";

  return ManagedObject.extend("my.app.controller.HelloDialog", {
    constructor: function (view) {
      ManagedObject.call(this);
      this._view = view;
    },

    open: function () {
      if (!this._pDialog) {
        this._pDialog = Fragment.load({
          id: this._view.getId(),
          name: "my.app.view.HelloDialog",
          controller: this // handlers like .onCloseDialog are looked up here
        }).then(function (dialog) {
          this._view.addDependent(dialog);
          return dialog;
        }.bind(this));
      }
      return this._pDialog.then(function (dialog) {
        dialog.open();
      });
    },

    onCloseDialog: function () {
      this._pDialog.then(function (dialog) {
        dialog.close();
      });
    }
  });
});

