onOpenSettings: async function () {
  if (!this._settingsDialog) {
    this._settingsDialog = await Fragment.load({
      id: this.getView().getId(),
      name: "my.app.view.SettingsDialog",
      controller: this
    });
    // the dialog now sees the view's models (i18n, default, ...)
    // and is destroyed when the view is destroyed
    this.getView().addDependent(this._settingsDialog);
  }
  this._settingsDialog.open();
}

